<?php /** @var string $entity */ /** @var array<string,mixed> $d */ /** @var list<array<string,mixed>> $rows */ /** @var string $status */ /** @var bool $canEdit */ /** @var bool $canPublish */
$badge = ['published' => 'ok', 'draft' => 'warn', 'closed' => 'warn', 'archived' => 'warn']; ?>
<div class="page-head"><div><p class="eyebrow">Website</p><h1><?= e($d['label']) ?></h1></div><?php if ($canEdit && empty($d['noCreate'])) : ?><a class="btn btn-primary" href="/admin/site/<?= e($entity) ?>/new">Add <?= e($d['singular']) ?></a><?php endif; ?></div>
<?= \Vertex\Core\View::partial('cms-nav') ?>
<p class="muted"><?= e($d['help']) ?></p>
<form method="get" class="toolbar"><div class="field"><label for="st">Show</label><select id="st" name="status"><option value="">Everything</option><?php foreach ($d['statuses'] as $s) : ?><option value="<?= e($s) ?>"<?= $status === $s ? ' selected' : '' ?>><?= e(ucfirst($s)) ?></option><?php endforeach; ?></select></div><div class="field"><button class="btn btn-ghost" type="submit">Filter</button></div></form>
<div class="table-wrap"><table class="table"><thead><tr><th><?= e(ucfirst($d['singular'])) ?></th><?php if ($entity === 'team') : ?><th>Group</th><?php endif; ?><?php if ($entity === 'faqs') : ?><th>Category</th><?php endif; ?><?php if ($entity === 'policies') : ?><th>Effective</th><th>Version</th><?php endif; ?><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r) : $t = (string) $r[$d['title']]; ?>
    <tr><td><a href="/admin/site/<?= e($entity) ?>/<?= e($r['public_id']) ?>"><?= e($t) ?></a><?php if (($d['slug'] ?? false) && !empty($r['slug'])) : ?><br><span class="muted small"><?= e($d['public'] . $r['slug']) ?></span><?php endif; ?></td>
        <?php if ($entity === 'team') : ?><td><?= e($r['department']) ?></td><?php endif; ?><?php if ($entity === 'faqs') : ?><td><?= e($r['category']) ?></td><?php endif; ?>
        <?php if ($entity === 'policies') : ?><td><?= $r['effective_date'] ? e(local_date((string) $r['effective_date'])) : '—' ?></td><td>v<?= (int) $r['version_no'] ?></td><?php endif; ?>
        <td><span class="badge badge-sys-<?= $badge[$r['status']] ?? 'warn' ?>"><?= e($r['status']) ?></span></td><td><?= e(local_time((string) $r['updated_at'])) ?></td>
        <td class="actions"><?php if ($canEdit && $entity !== 'policies') : ?><form method="post" action="/admin/site/<?= e($entity) ?>/<?= e($r['public_id']) ?>/move" class="inline-form"><?= csrf_field() ?><button class="btn btn-ghost btn-sm" name="dir" value="up" type="submit" aria-label="Move up">↑</button><button class="btn btn-ghost btn-sm" name="dir" value="down" type="submit" aria-label="Move down">↓</button></form><?php endif; ?></td></tr>
<?php endforeach; ?>
<?php if ($rows === []) : ?><tr><td colspan="7" class="muted">Nothing here yet.<?php if ($canEdit && empty($d['noCreate'])) : ?> <a href="/admin/site/<?= e($entity) ?>/new">Add the first one.</a><?php endif; ?></td></tr><?php endif; ?></tbody></table></div>
